package com.centralplay.app.ui;

import android.os.Bundle;import android.view.*;import android.widget.TextView;import androidx.annotation.*;import androidx.fragment.app.Fragment;import com.centralplay.app.R;import com.centralplay.app.data.*;import com.centralplay.app.model.Catalog;import java.text.DateFormat;import java.util.Date;
public class HomeFragment extends Fragment {private TextView status,counts;public HomeFragment(){super(R.layout.fragment_home);}@Override public void onViewCreated(@NonNull View v,@Nullable Bundle b){status=v.findViewById(R.id.status_text);counts=v.findViewById(R.id.counts_text);refresh();}public void refresh(){if(getContext()==null||status==null)return;Catalog c=CatalogRepository.get(requireContext()).getCachedCatalog();long t=Prefs.syncTime(requireContext());String when=t==0?"sin sincronizar":DateFormat.getDateTimeInstance(DateFormat.SHORT,DateFormat.SHORT).format(new Date(t));String err=Prefs.syncError(requireContext());status.setText(Prefs.syncSource(requireContext())+" · "+when+(err.trim().isEmpty()?"":"\nÚltimo error: "+err));counts.setText("TV: "+c.live.size()+"   ·   Películas: "+c.movies.size()+"   ·   Series: "+c.series.size());}}
